import queue
import threading
import logging
from typing import Callable, Any, Optional


logger = logging.getLogger(__name__)


class QueueWorker:
    def __init__(self, process_fn: Callable, queue_size: int = 0):
        self.process_fn = process_fn
        self.task_queue = queue.Queue(maxsize=queue_size)
        self.thread = None
        self.running = False

    def start(self) -> None:
        if self.running:
            return
        self.running = True
        self.thread = threading.Thread(target=self._process_loop, daemon=False)
        self.thread.start()

    def stop(self, timeout: Optional[float] = None) -> None:
        if not self.running:
            return
        self.running = False
        self.task_queue.put(None)
        if self.thread:
            self.thread.join(timeout=timeout)

    def submit(self, item: Any) -> None:
        if not self.running:
            raise RuntimeError("Worker not started")
        self.task_queue.put(item)

    def _process_loop(self) -> None:
        while self.running:
            try:
                item = self.task_queue.get(timeout=1.0)
                if item is None:
                    break
                self.process_fn(item)
            except queue.Empty:
                continue
            except Exception as e:
                logger.exception("Error processing item")


if __name__ == "__main__":
    def process_item(item):
        print(f"Processing: {item}")

    worker = QueueWorker(process_item)
    worker.start()

    for i in range(5):
        worker.submit(i)

    worker.stop(timeout=5)
